-- ----------------------------
-- Table structure for goods
-- ----------------------------
DROP TABLE IF EXISTS `goods`;
CREATE TABLE `goods` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `ingredients` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `specs` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shelf_life` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `weight` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `origin` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `serves` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图片',
  `price` double(10,2) DEFAULT NULL COMMENT '价格',
  `num` int DEFAULT NULL COMMENT '库存',
  `unit` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '单位',
  `category_id` int DEFAULT NULL COMMENT '分类ID',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=147 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='蛋糕信息';

-- ----------------------------
-- Records of goods
-- ----------------------------
BEGIN;
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (1, '晨光玫瑰', '玫瑰花瓣与香草奶油的初见，温柔如晨光。', '【晨光玫瑰】\n\n造型：象牙白奶油抹面，缀以新鲜玫瑰花瓣，简约而温柔。\n\n口感：戚风胚松软湿润，夹层为低糖香草奶油，清甜不腻。\n\n工艺：24小时内现做现发，全程冷链。\n\n场景：情人节、纪念日、求婚。', '小麦粉、鸡蛋、白砂糖、法国稀奶油、马达加斯加香草荚、食用玫瑰花瓣、吉利丁。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约450g / 8寸 约750g', '上海·中央厨房手工制作', '6寸 2-4人份 / 8寸 4-8人份', 'http://127.0.0.1:9090/files/download/1-1.jpeg', 98.00, 12, '份', 1);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (3, '月白色调', '月光下的告白，奶油与白巧克力的低语。', '【月白色调】\n\n造型：极简裸蛋糕，侧边露出胚体纹理，顶部铺白巧克力碎。\n\n口感：日式棉花蛋糕胚+马斯卡彭奶酪，绵密如云。\n\n场景：纪念日、约会、求婚。', '小麦粉、鸡蛋、白砂糖、稀奶油、白巧克力、马斯卡彭奶酪、香草荚。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约450g / 8寸 约750g', '上海·中央厨房手工制作', '6寸 2-4人份 / 8寸 4-8人份', 'http://127.0.0.1:9090/files/download/1-2.jpeg', 108.00, 8, '份', 1);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (4, '焦糖暖意', '海盐焦糖的微咸回甘，是冬夜的拥抱。', '【焦糖暖意】\n\n造型：奶咖色抹面，淋面海盐焦糖，简约大方。\n\n口感：戚风胚+海盐焦糖夹心，咸甜层次丰富。\n\n场景：秋冬季约会、纪念日。', '小麦粉、鸡蛋、白砂糖、稀奶油、海盐焦糖酱、比利时巧克力、黄油。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 2-4人份 / 8寸 4-8人份', 'http://127.0.0.1:9090/files/download/1-3.jpeg', 108.00, 10, '份', 1);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (5, '黑金誓言', '黑巧与金箔，是属于夜晚的庄重承诺。', '【黑金誓言】\n\n造型：哑光黑巧抹面，金箔点缀，仪式感十足。\n\n口感：比利时 70% 黑巧+戚风胚，醇厚微苦。\n\n场景：订婚、纪念日、生日惊喜。', '小麦粉、鸡蛋、白砂糖、比利时 70% 黑巧克力、稀奶油、食用金箔、可可粉。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 2-4人份 / 8寸 4-8人份', 'http://127.0.0.1:9090/files/download/1-4.jpeg', 128.00, 6, '份', 1);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (6, '红丝绒之夜', '红丝绒与奶酪霜的经典重逢。', '【红丝绒之夜】\n\n造型：深红丝绒胚+白色奶酪霜花纹，复古优雅。\n\n口感：绵密丝滑胚体+酸甜奶酪霜，层次分明。\n\n场景：情人节、纪念日。', '小麦粉、鸡蛋、白砂糖、黄油、可可粉、红曲粉、奶油奶酪、香草荚。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约480g / 8寸 约800g', '上海·中央厨房手工制作', '6寸 2-4人份 / 8寸 4-8人份', 'http://127.0.0.1:9090/files/download/1-5.jpeg', 118.00, 9, '份', 1);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (7, '童画森林', '森系小动物造型，孩子生日的主角。', '【童画森林】\n\n造型：森林主题+小动物糖艺，色彩自然柔和。\n\n工艺：色素全部植物提取，无人工添加。\n\n场景：儿童生日、家庭聚会。', '小麦粉、鸡蛋、白砂糖、稀奶油、新鲜水果、翻糖、天然色素（甜菜根、姜黄）。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 4-6人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/2-1.jpeg', 98.00, 10, '份', 2);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (8, '小熊派对', '憨萌小熊糖艺，承包小朋友的笑颜。', '【小熊派对】\n\n造型：奶油抹面+巧克力小熊摆件，童趣十足。\n\n口感：戚风胚+草莓夹心，小朋友最爱。\n\n场景：儿童生日、幼儿园庆祝。', '小麦粉、鸡蛋、白砂糖、稀奶油、巧克力、翻糖、新鲜草莓。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 4-6人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/2-2.jpeg', 98.00, 8, '份', 2);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (9, '奇幻气球', '彩色糖艺气球，载着童心飞起。', '【奇幻气球】\n\n造型：糖艺气球+云朵奶油，梦幻派对氛围。\n\n工艺：糖艺手工拉制，每个气球可食用。\n\n场景：儿童生日、主题派对。', '小麦粉、鸡蛋、白砂糖、稀奶油、糖艺装饰、食用色素、混合水果。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 4-6人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/2-3.jpeg', 108.00, 12, '份', 2);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (10, '棉花糖云', '棉花糖云朵+彩虹糖珠，是甜的梦。', '【棉花糖云】\n\n造型：白色奶油云朵+彩色棉花糖+糖珠，仙气十足。\n\n口感：戚风胚+香草奶油+棉花糖夹心，甜而不腻。\n\n场景：儿童生日、女孩派对。', '小麦粉、鸡蛋、白砂糖、稀奶油、棉花糖、糖珠、香草荚。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 4-6人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/2-4.jpeg', 98.00, 9, '份', 2);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (11, '蓝天朵朵', '晴空与白云的造型，明亮又温柔。', '【蓝天朵朵】\n\n造型：浅蓝滴落抹面+白色云朵糖艺，清新明亮。\n\n口感：白巧+香草奶油，温和易接受。\n\n场景：儿童生日、洗礼宴。', '小麦粉、鸡蛋、白砂糖、稀奶油、糖艺云朵、白巧克力、香草荚。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 4-6人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/2-5.jpeg', 98.00, 10, '份', 2);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (12, '都市极简', '奶油抹面留白，是给职场庆生的得体之选。', '【都市极简】\n造型：纯白奶油抹面+巧克力牌，干净简约。\n口感：香草戚风+白巧奶油，温和大众。\n场景：同事生日、办公室庆祝。', '小麦粉、鸡蛋、白砂糖、稀奶油、白巧克力、香草荚、新鲜水果。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 3-5人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/3-1.jpeg', 98.00, 12, '份', 3);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (13, '老友记', '榛子与巧克力的经典搭配，如老友般熟悉。', '【老友记】\n造型：奶咖色抹面+榛子碎围边，沉稳低调。\n口感：榛子巧克力胚+黑巧奶油，醇厚经典。\n场景：朋友聚会、兄弟生日。', '小麦粉、鸡蛋、白砂糖、稀奶油、榛子、黑巧克力、可可粉、香草荚。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 3-5人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/3-2.jpeg', 108.00, 8, '份', 3);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (14, '周末午后', '伯爵红茶蛋糕，是慢下来的下午。', '【周末午后】\n造型：奶白色抹面+红茶茶叶点缀，文艺气息。\n口感：伯爵红茶胚+红茶奶油，茶香悠长。\n场景：闺蜜聚会、下午茶。', '小麦粉、鸡蛋、白砂糖、稀奶油、伯爵红茶、佛手柑精油、香草荚。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 3-5人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/3-3.jpeg', 98.00, 10, '份', 3);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (15, '暖阳红茶', '红茶与杏肉的搭配，午后暖阳的味道。', '【暖阳红茶】\n造型：奶橘色调抹面+杏片装饰，温暖明亮。\n口感：红茶戚风+杏肉夹心，酸甜温暖。\n场景：同事庆祝、朋友聚会。', '小麦粉、鸡蛋、白砂糖、稀奶油、红茶、杏肉、肉桂、香草荚。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 3-5人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/3-4.jpeg', 108.00, 9, '份', 3);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (16, '黑白对话', '黑巧与香草的双拼，是不同口味的共识。', '【黑白对话】\n造型：一半黑巧一半香草，对比鲜明。\n口感：双拼胚体+对应口味奶油，一次尝两种风味。\n场景：同事生日、口味多元的聚会。', '小麦粉、鸡蛋、白砂糖、稀奶油、比利时黑巧克力、马达加斯加香草荚。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 3-5人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/3-5.jpeg', 108.00, 11, '份', 3);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (17, '仙气裸蛋糕', '裸蛋糕与可食用花，仙气十足。', '【仙气裸蛋糕】\n造型：侧边裸露胚体纹理，顶部铺可食用花与莓果。\n工艺：花朵有机种植，安全可食。\n场景：闺蜜生日、新娘婚前派对。', '小麦粉、鸡蛋、白砂糖、稀奶油、有机可食用花（三色堇、玫瑰）、新鲜莓果。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约450g / 8寸 约750g', '上海·中央厨房手工制作', '6寸 2-4人份 / 8寸 4-8人份', 'http://127.0.0.1:9090/files/download/4-1.jpeg', 128.00, 8, '份', 4);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (18, '简约潮酷', '黑灰金三色，几何切面设计，沉稳大气。', '【简约潮酷】\n造型：黑灰金三色+几何切面+车厘子与金箔点缀。\n口感：比利时 70% 黑巧+榛子，醇厚微苦。\n场景：男友生日、兄弟聚会。', '小麦粉、鸡蛋、白砂糖、比利时 70% 黑巧克力、榛子、稀奶油、可可粉、食用金箔。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 3-5人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/5-1.jpeg', 108.00, 10, '份', 5);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (19, '福寿安康', '寿桃造型+寿字糖艺，传统喜庆。', '【福寿安康】\n造型：红色寿桃造型+寿字糖艺，传统喜庆。\n工艺：低糖低脂配方，糖度降低 40%，木糖醇部分替代蔗糖。\n场景：父母寿宴、长辈生日。', '小麦粉、鸡蛋、木糖醇、白砂糖、稀奶油、新鲜水果、寿桃造型翻糖、天然色素（甜菜根）。', '8寸 / 10寸', '冷藏 0-4℃ 24小时内食用最佳', '8寸 约850g / 10寸 约1200g', '上海·中央厨房手工制作', '8寸 6-10人份 / 10寸 10-16人份', 'http://127.0.0.1:9090/files/download/6-1.jpeg', 128.00, 8, '份', 6);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (20, '轻奢双层', '双层鲜花+绸缎裱花，富丽典雅。', '【轻奢双层】\n造型：双层结构，上层鲜花装饰+下层绸缎裱花，金箔与糖艺寿字点缀。\n口感：上层香草胚+下层巧克力胚，一蛋糕两口味。\n场景：宴席、大寿、婚礼。', '小麦粉、鸡蛋、白砂糖、稀奶油、比利时巧克力、马达加斯加香草荚、新鲜水果、食用金箔、翻糖。', '双层 8+10寸 / 双层 10+12寸', '冷藏 0-4℃ 24小时内食用最佳', '8+10寸 约2000g / 10+12寸 约2800g', '上海·中央厨房手工制作', '15-25人份', 'http://127.0.0.1:9090/files/download/7-1.jpeg', 288.00, 6, '份', 7);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (96, '莓果初见', '覆盆子与香草的清爽相遇，像初恋的味道。', '【莓果初见】\n\n造型：白色奶油抹面，顶部铺满新鲜莓果，自然清新。\n\n口感：戚风胚+莓果夹心，酸甜平衡。\n\n场景：春夏季约会、生日。', '小麦粉、鸡蛋、白砂糖、稀奶油、覆盆子、蓝莓、黑莓、香草荚、吉利丁。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约480g / 8寸 约800g', '上海·中央厨房手工制作', '6寸 2-4人份 / 8寸 4-8人份', 'http://127.0.0.1:9090/files/download/1-1.jpeg', 118.00, 7, '份', 1);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (97, '鸢尾情诗', '鸢尾花萃取的清雅，是给懂得的人的诗。', '【鸢尾情诗】\n\n造型：淡紫色奶油抹面，糖花点缀，优雅低调。\n\n口感：法式鸢尾奶油+蓝莓夹心，花香与果香交织。\n\n场景：求婚、重要纪念日。', '小麦粉、鸡蛋、白砂糖、法国稀奶油、鸢尾花萃取、蓝莓果酱、香草荚。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 2-4人份 / 8寸 4-8人份', 'http://127.0.0.1:9090/files/download/1-2.jpeg', 128.00, 5, '份', 1);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (98, '极光慕斯', '渐变紫蓝如极光，是梦里的甜。', '【极光慕斯】\n\n造型：渐变紫蓝慕斯镜面，宛若极光流动。\n\n口感：蓝莓慕斯+戚风底，轻盈清新。\n\n场景：生日、惊喜派对。', '小麦粉、鸡蛋、白砂糖、稀奶油、蓝莓、蝶豆花、柠檬汁、吉利丁。', '6寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g', '上海·中央厨房手工制作', '4-6人份', 'http://127.0.0.1:9090/files/download/1-3.jpeg', 138.00, 6, '份', 1);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (99, '晨雾白桃', '白桃与玫瑰的双层慕斯，清新如晨雾。', '【晨雾白桃】\n\n造型：奶白慕斯层+粉桃果冻层，淡雅如晨雾。\n\n口感：白桃果肉+玫瑰慕斯，清爽不甜腻。\n\n场景：春夏季约会、生日。', '小麦粉、鸡蛋、白砂糖、稀奶油、白桃果肉、玫瑰水、吉利丁、香草荚。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约480g / 8寸 约800g', '上海·中央厨房手工制作', '6寸 2-4人份 / 8寸 4-8人份', 'http://127.0.0.1:9090/files/download/1-4.jpeg', 108.00, 11, '份', 1);
