INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (101, '糖果游乐园', '缤纷糖果造型，是一座甜蜜乐园。', '【糖果游乐园】\n\n造型：旋转木马+气球糖艺，缤纷糖果色。\n\n工艺：糖艺全手工捏制，可定制小朋友名字。\n\n场景：儿童生日、主题派对。', '小麦粉、鸡蛋、白砂糖、稀奶油、糖艺装饰、食用色素、新鲜水果。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 4-6人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/2-1.jpeg', 108.00, 11, '份', 2);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (102, '森系小屋', '森林里的小木屋，装满童年的想象。', '【森系小屋】\n\n造型：巧克力木屋+蘑菇糖艺+食用苔藓，自然森系。\n\n口感：巧克力胚+莓果夹心，酸甜平衡。\n\n场景：儿童生日、家庭聚会。', '小麦粉、鸡蛋、白砂糖、稀奶油、巧克力、翻糖、新鲜莓果、食用花朵。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 4-6人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/2-2.jpeg', 108.00, 7, '份', 2);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (103, '海洋奇缘', '海浪与小鱼，是夏日里的童趣。', '【海洋奇缘】\n\n造型：渐变蓝海洋抹面+糖艺小鱼+海浪花纹，清爽夏日感。\n\n口感：蓝莓慕斯+戚风底，清凉酸甜。\n\n场景：夏季生日、泳池派对。', '小麦粉、鸡蛋、白砂糖、稀奶油、蓝莓、蝶豆花、吉利丁、糖艺海洋生物。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 4-6人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/2-3.jpeg', 118.00, 8, '份', 2);
