INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (123, '极简之心', '纯黑抹面+一颗金心，少即是多。', '【极简之心】\n造型：哑光黑抹面+金色爱心，极简而有力。\n口感：黑巧胚+香草奶油，苦甜平衡。\n场景：男友生日、纪念日。', '小麦粉、鸡蛋、白砂糖、黑巧克力、可可粉、食用金箔、稀奶油。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 3-5人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/5-1.jpeg', 98.00, 10, '份', 5);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (124, '暮色巧克力', '多层巧克力结构，浓郁如暮色。', '【暮色巧克力】\n造型：渐变深浅巧克力层+海盐结晶点缀。\n口感：四层巧克力结构（胚+慕斯+甘纳许+脆片），层次饱满。\n场景：巧克力爱好者生日。', '小麦粉、鸡蛋、白砂糖、比利时 70% 黑巧克力、稀奶油、可可粉、黄油、海盐。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 3-5人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/5-1.jpeg', 128.00, 9, '份', 5);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (125, '黑曜石', '镜面黑亮如黑曜石，神秘冷峻。', '【黑曜石】\n造型：黑色镜面+银箔点缀，质感冷峻。\n口感：黑巧慕斯+戚风底，浓郁丝滑。\n场景：男士生日、商务庆典。', '小麦粉、鸡蛋、白砂糖、黑巧克力、稀奶油、可可粉、吉利丁、食用银箔。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 3-5人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/5-1.jpeg', 148.00, 4, '份', 5);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (126, '钢铁意志', '灰金配色+机械齿轮糖艺，硬核风格。', '【钢铁意志】\n造型：灰金配色+齿轮糖艺，工业风硬朗。\n口感：黑巧胚+榛子脆片，浓郁带脆感。\n场景：工程师/机械爱好者生日。', '小麦粉、鸡蛋、白砂糖、黑巧克力、稀奶油、可可粉、糖艺齿轮、食用金箔。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 3-5人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/5-1.jpeg', 128.00, 6, '份', 5);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (127, '雪松之夜', '雪松糖艺+深色抹面，森林深夜的气息。', '【雪松之夜】\n造型：深色抹面+雪松糖艺+银珠，沉静森林感。\n口感：黑巧胚+海盐奶油，沉稳深邃。\n场景：男士生日、冬季庆典。', '小麦粉、鸡蛋、白砂糖、黑巧克力、稀奶油、可可粉、糖艺雪松、食用银珠。', '6寸 / 8寸', '冷藏 0-4℃ 24小时内食用最佳', '6寸 约500g / 8寸 约850g', '上海·中央厨房手工制作', '6寸 3-5人份 / 8寸 6-10人份', 'http://127.0.0.1:9090/files/download/5-1.jpeg', 148.00, 5, '份', 5);
