INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (129, '长青松柏', '松柏造型糖艺，寓意长青不老。', '【长青松柏】\n造型：抹茶绿色调+松柏糖艺，沉稳大气。\n口感：抹茶胚+红豆夹心，清雅微苦。\n场景：长辈寿宴、父亲生日。', '小麦粉、鸡蛋、白砂糖、稀奶油、抹茶粉、寿桃糖艺、新鲜水果、吉利丁。', '8寸 / 10寸', '冷藏 0-4℃ 24小时内食用最佳', '8寸 约850g / 10寸 约1200g', '上海·中央厨房手工制作', '8寸 6-10人份 / 10寸 10-16人份', 'http://127.0.0.1:9090/files/download/6-1.jpeg', 148.00, 6, '份', 6);
