INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (140, '双心同庆', '双心结构+鲜花，结婚纪念日的甜。', '【双心同庆】\n造型：双层爱心结构+鲜花装饰，浪漫温馨。\n口感：覆盆子+香草双层，酸甜层次。\n场景：结婚纪念日、求婚宴。', '小麦粉、鸡蛋、白砂糖、稀奶油、覆盆子、玫瑰花瓣、香草荚、食用金箔。', '双层 6+8寸', '冷藏 0-4℃ 24小时内食用最佳', '约 1800g', '上海·中央厨房手工制作', '10-18人份', 'http://127.0.0.1:9090/files/download/7-1.jpeg', 288.00, 5, '份', 7);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (141, '三层华庭', '三层宴会大作，富丽堂皇。', '【三层华庭】\n造型：三层结构+花园主题+金箔点缀，宴会主角。\n口感：香草+巧克力+红丝绒三层风味。\n场景：大型宴席、家族庆典。', '小麦粉、鸡蛋、白砂糖、稀奶油、白巧克力、食用金箔、翻糖、糖艺装饰、新鲜水果、食用花朵。', '三层 6+8+10寸', '冷藏 0-4℃ 24小时内食用最佳', '约 3200g', '上海·中央厨房手工制作', '20-35人份', 'http://127.0.0.1:9090/files/download/7-1.jpeg', 488.00, 2, '份', 7);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (142, '庆典之巅', '四层庆典蛋糕，大型活动主角。', '【庆典之巅】\n造型：四层结构+繁复糖艺+金箔，极致奢华。\n口感：四种风味分层（香草/巧克力/红丝绒/抹茶）。\n场景：大型企业庆典、百人宴席。', '小麦粉、鸡蛋、白砂糖、稀奶油、白巧克力、翻糖、糖艺装饰、食用金箔、新鲜水果、可食用花。', '四层 6+8+10+12寸', '冷藏 0-4℃ 24小时内食用最佳', '约 5000g', '上海·中央厨房手工制作', '35-60人份', 'http://127.0.0.1:9090/files/download/7-1.jpeg', 688.00, 2, '份', 7);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (143, '维多利亚', '维多利亚风+蕾丝糖艺，复古典雅。', '【维多利亚】\n造型：双层结构+蕾丝糖艺+珍珠装饰，维多利亚复古风。\n口感：法国奶油+玫瑰夹心，温柔典雅。\n场景：复古婚礼、下午茶宴。', '小麦粉、鸡蛋、白砂糖、法国稀奶油、白巧克力、翻糖蕾丝、玫瑰花瓣、食用珍珠、香草荚。', '双层 8+10寸', '冷藏 0-4℃ 24小时内食用最佳', '约 2300g', '上海·中央厨房手工制作', '15-25人份', 'http://127.0.0.1:9090/files/download/7-1.jpeg', 368.00, 3, '份', 7);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (144, '雪山叠嶂', '雪山造型双层，纯洁震撼。', '【雪山叠嶂】\n造型：双层雪山结构+椰蓉雪花+银箔，纯洁震撼。\n口感：椰香+白巧双层，清爽纯净。\n场景：冬季婚礼、白色主题宴。', '小麦粉、鸡蛋、白砂糖、稀奶油、白巧克力、椰蓉、糖艺雪松、食用银箔。', '双层 8+10寸', '冷藏 0-4℃ 24小时内食用最佳', '约 2200g', '上海·中央厨房手工制作', '15-25人份', 'http://127.0.0.1:9090/files/download/7-1.jpeg', 328.00, 4, '份', 7);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (145, '浮世双层', '日式浮世绘风糖艺，东方意境。', '【浮世双层】\n造型：双层结构+日式浮世绘糖艺+樱花点缀，东方意境。\n口感：抹茶+红豆+樱花三层风味。\n场景：和风婚礼、寿宴。', '小麦粉、鸡蛋、白砂糖、稀奶油、抹茶粉、红豆、糖艺浮世绘、樱花、食用金箔。', '双层 8+10寸', '冷藏 0-4℃ 24小时内食用最佳', '约 2300g', '上海·中央厨房手工制作', '15-25人份', 'http://127.0.0.1:9090/files/download/7-1.jpeg', 388.00, 3, '份', 7);
INSERT INTO `goods` (`id`, `name`, `description`, `detail`, `ingredients`, `specs`, `shelf_life`, `weight`, `origin`, `serves`, `img`, `price`, `num`, `unit`, `category_id`) VALUES (146, '繁花盛典', '三层繁花装饰，宴席中的艺术品。', '【繁花盛典】\n造型：三层结构+全糖艺繁花装饰+金箔，繁复华丽。\n口感：法国奶油+多水果夹心，层次丰富。\n场景：豪华婚礼、年度盛典。', '小麦粉、鸡蛋、白砂糖、法国稀奶油、白巧克力、翻糖花、可食用鲜花、食用金箔、新鲜水果。', '三层 6+8+10寸', '冷藏 0-4℃ 24小时内食用最佳', '约 3300g', '上海·中央厨房手工制作', '25-40人份', 'http://127.0.0.1:9090/files/download/7-1.jpeg', 528.00, 2, '份', 7);
COMMIT;

-- ----------------------------
-- Table structure for index_task
-- ----------------------------
DROP TABLE IF EXISTS `index_task`;
CREATE TABLE `index_task` (
  `id` int NOT NULL AUTO_INCREMENT,
  `entity_type` varchar(32) NOT NULL DEFAULT 'goods',
  `entity_id` int NOT NULL,
  `action` varchar(16) NOT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'pending',
  `attempts` int NOT NULL DEFAULT '0',
  `last_error` longtext,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='向量索引 outbox：MySQL 业务提交后写入，后台任务异步同步到 ChromaDB。';

-- ----------------------------
-- Records of index_task
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for knowledge
