INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (76, 'assistant', '您的订单信息如下：\n\n- **订单号**：202607041055292078  \n- **商品**：轻奢双层祝寿蛋糕  \n- **数量**：2  \n- **单价**：¥188.0  \n- **总价**：¥376.0  \n- **收货地址**：123  \n- **下单时间**：2026-07-04 10:55:29  \n- **状态**：待发货  \n\n如需进一步操作（如取消订单），请告知我。', '2026-08-06 07:20:27.417217', 11);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (77, 'user', '那个订单适合什么人群', '2026-08-06 07:20:45.759637', 11);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (78, 'assistant', '根据查询到的信息，\"轻奢双层祝寿蛋糕\"适合以下人群：\n\n- **生日庆祝**：适合为亲朋好友庆祝生日，尤其是注重品质和氛围感的用户。\n- **长辈祝福**：适合送给父母、祖父母等长辈，表达敬意与祝福。\n- **朋友聚会**：适合用于朋友间的庆生派对，体现用心与情谊。\n- **纪念日庆祝**：如结婚纪念日、友情纪念日等特殊日子，可传递温暖情感。\n\n如果您有特定的使用场景或人群需求，我可以进一步为您推荐合适的蛋糕款式哦！🎂', '2026-08-06 07:20:49.125176', 11);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (89, 'user', '推荐一款生日蛋糕', '2026-08-06 08:12:58.295676', 13);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (90, 'assistant', '我可以根据您的需求为您推荐一款蛋糕。请问您有特别的口味偏好、送礼对象或使用场景吗？比如是给孩子、朋友还是恋人，或者是否有特定的口味喜好（如巧克力、水果等）？', '2026-08-06 08:12:59.675262', 13);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (91, 'user', '送长辈', '2026-08-06 08:13:08.978365', 13);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (92, 'assistant', '根据您的需求，我为您推荐以下蛋糕：\n\n1. **经典红丝绒蛋糕** - ¥98.0（有货，剩余12份）  \n   适合长辈的口味，口感细腻，浓郁的红丝绒风味，搭配精致的装饰，是表达敬意和祝福的佳选。\n\n2. **香草奶油慕斯蛋糕** - ¥88.0（有货，剩余15份）  \n   清爽不腻，香草味浓郁，适合喜欢简单口味的长辈，外观优雅，适合各种生日场合。\n\n3. **核桃巧克力蛋糕** - ¥78.0（有货，剩余18份）  \n   巧克力与核桃的完美结合，口感丰富，适合喜欢浓郁口味的长辈。\n\n如果您有其他偏好或需要进一步帮助，请随时告诉我！🎂', '2026-08-06 08:13:12.196596', 13);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (93, 'user', '查询我的订单', '2026-08-06 08:13:45.179163', 13);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (94, 'assistant', '您最近的 3 笔订单如下：\n\n1. **订单号**：202607041547335041  \n   - 商品：浪漫爱心情侣蛋糕 x1  \n   - 金额：¥88.0  \n\n2. **订单号**：202607041055292078  \n   - 商品：轻奢双层祝寿蛋糕 x2  \n   - 金额：¥376.0  \n\n3. **订单号**：202607041055091665  \n   - 商品：欢聚同乐蛋糕 x1  \n   - 金额：¥88.0  \n\n如果您需要查询某个具体订单的详细信息或状态，请告诉我订单号。', '2026-08-06 08:13:47.562484', 13);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (95, 'user', '推荐一款生日蛋糕', '2026-08-07 07:13:47.529792', 13);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (96, 'assistant', '根据当前商品库，为您找到以下蛋糕：\n1. **福寿安康祝寿蛋糕** — ¥108.0（库存 5份）\n   松软低脂口感温润，鲜果搭配软糯夹层，祝愿长辈平安健康福寿绵长。\n2. **职场同乐祝福蛋糕** — ¥88.0（库存 12份）\n   口感温润老少皆宜，造型简约大方，为同事生日送上真诚祝愿。\n3. **轻奢双层祝寿蛋糕** — ¥188.0（库存 18份）\n   双层造型大气华丽，用料扎实口感细腻，宴席聚会庆生场面十足。', '2026-08-07 07:13:49.233145', 13);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (97, 'user', '我想要退货', '2026-08-07 07:14:01.939947', 13);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (98, 'assistant', '根据我们的售后政策，蛋糕属于“易于腐败、保存期限较短”的商品，不适用七天无理由退货规定。但如果您遇到以下情况，可以申请售后服务：\n\n1. **蛋糕在运输途中发生严重毁损（倾倒、大面积变形、融化）**；\n2. **商品与订单不符（错送款式、尺寸、口味）**；\n3. **商品存在明显变质（异味、发霉、异物）**；\n4. **配件严重缺失（未按订单提供蜡烛、餐具、贺卡等）**。\n\n如果您符合以上任一情况，请在收到商品后 **24小时内** 联系客服，并提供以下凭证：\n- 开箱视频；\n- 商品照片（需清晰展示问题）；\n- 订单编号。\n\n客服将在 1-2 个工作日内审核，并根据情况提供补发、部分退款或全额退款。\n\n如果您不确定是否符合退货条件，可以先联系客服进一步确认。需要我帮您联系客服吗？', '2026-08-07 07:14:05.355185', 13);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (99, 'user', '联系客服', '2026-08-07 07:14:18.210322', 13);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (100, 'assistant', '您好，您可以通过以下方式联系甜心烘焙的客服团队：\n\n1. **在线客服**：点击页面右下角的“在线客服”按钮，即可与客服人员实时沟通。\n2. **电话客服**：拨打我们的客服热线 **400-123-4567**（工作时间：9:00 - 21:00）。\n3. **邮件客服**：发送邮件至 **service@sweethartsbakery.com**，我们会尽快回复。\n\n如果您需要进一步帮助，请随时告诉我！😊', '2026-08-07 07:14:20.273881', 13);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (101, 'user', '你们有什么口味的蛋糕', '2026-08-12 02:54:27.164588', 14);
INSERT INTO `message` (`id`, `role`, `content`, `created_at`, `conversation_id`) VALUES (102, 'assistant', '根据当前商品库，为您找到以下蛋糕：\n1. **元气童趣动漫蛋糕** — ¥108.0（库存 10份）\n   热门卡通人物创意装扮，颜值俏皮吸睛，清甜口味小朋友超喜爱。\n2. **欢聚同乐蛋糕** — ¥88.0（库存 7份）\n   简约大气颜值耐看，口味清爽不甜腻，适合同事朋友相聚庆喜乐。\n3. **简约潮酷男士蛋糕** — ¥88.0（库存 10份）\n   简约大气利落造型，口味醇厚不腻，适配男生生日沉稳大气风格。', '2026-08-12 02:54:29.290893', 14);
COMMIT;

-- ----------------------------
-- Table structure for notice
-- ----------------------------
DROP TABLE IF EXISTS `notice`;
CREATE TABLE `notice` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标题',
  `content` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '内容',
  `time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公告信息';

-- ----------------------------
-- Records of notice
-- ----------------------------
BEGIN;
INSERT INTO `notice` (`id`, `name`, `content`, `time`) VALUES (1, '智能商城导购与运营平台', '智能商城导购与运营平台Beta版今日已上线！', '2026-05-19 21:10:13');
INSERT INTO `notice` (`id`, `name`, `content`, `time`) VALUES (2, '111', '111111111111111111111111111111111111111111111111111111', '2026-05-19 21:10:45');
COMMIT;

-- ----------------------------
-- Table structure for orders
-- ----------------------------
DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `order_no` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `num` int DEFAULT NULL COMMENT '数量',
  `user_id` int DEFAULT NULL COMMENT '用户ID',
  `goods_id` int DEFAULT NULL COMMENT '商品ID',
  `address_id` int DEFAULT NULL COMMENT '地址ID',
  `time` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '下单时间',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '待发货' COMMENT '订单状态：待发货/已发货/已签收/已评价/已取消',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='订单信息';

-- ----------------------------
-- Records of orders
-- ----------------------------
BEGIN;
